__bsl_cr() { p=$(command -v -- "$1" 2>/dev/null) || return 1; p=$(readlink -f "$p" 2>/dev/null) || return 1; d=${p%/*}; for x in "$d" "${d%/*}"; do { [ -f "$x/chrome_100_percent.pak" ] || [ -f "$x/v8_context_snapshot.bin" ]; } && return 0; done; [ "$2" = 1 ] && return 1; [ "$(head -c 2 "$p" 2>/dev/null)" = '#!' ] || return 1; for w in $(head -c 8192 "$p" | tr -s " \t\"'" '\n\n\n\n' | awk 'prev == "exec" && $0 !~ /^[-<]/ && $0 !~ /=/ { print } /^\// { print } { prev = $0 }' | head -n 32); do __bsl_cr "$w" 1 && return 0; done; return 1; }; set -- 'bsl-fake-electron' '--x'; f=; for w in 'bsl-fake-electron'; do __bsl_cr "$w" 0 && f=1 && break; done; [ -n "$f" ] && set -- "$@" '--force-device-scale-factor=1.5'; exec "$@"
